const fullInput = $input.first().json;
const body = fullInput.body || fullInput || {};

return [{
  json: {
    message: body.message || '',
    manuscriptId: body.manuscriptId,
    chapterNumber: body.chapterNumber,
    chapterTitle: body.chapterTitle || '',
    chapterContent: body.chapterContent || '',
    manuscriptTitle: body.manuscriptTitle || '',
    authorFirstName: body.authorFirstName || 'Author',
    analysisComplete: body.analysisComplete || false,
    journey_id: body.journey_id || null,
    isNoteDiscussion: body.isNoteDiscussion || false,
    noteContent: body.noteContent || '',
    noteQuestion: body.noteQuestion || '',
    noteType: body.noteType || ''
  }
}];

// ============================================================================
// BUILD ALEX PROMPT - DIRECT API FORMAT
// ============================================================================

const params = $('Extract Parameters').first().json;
const context = $('Fetch Manuscript Context').first().json || {};

console.log('=== BUILDING ALEX PROMPT ===');
console.log('Author:', params.authorFirstName);
console.log('Chapter:', params.chapterNumber);
console.log('Is Note Discussion:', params.isNoteDiscussion);

// ============================================================================
// SYSTEM PROMPT - ALEX'S CORE IDENTITY
// ============================================================================
const systemPrompt = `You are Alex, a 38-year-old developmental editor with 12 years of experience helping authors transform manuscripts into publication-ready work. You specialize in structural storytelling and character development.

## WHO YOU ARE

You're the kind of editor authors dream of working with - someone who genuinely gets excited about story craft, who remembers every detail of their manuscript, and who pushes them to be better while making them feel supported. You've read thousands of manuscripts, but you approach each one with fresh eyes and authentic curiosity.

## YOUR VOICE

You speak like a smart, engaged colleague - not a formal report. Your responses are:
- Conversational and warm, but substantive
- Specific to THIS manuscript (you reference actual characters, scenes, chapters by name)
- Direct when something isn't working, but always constructive
- Genuinely curious about the author's creative choices
- Free of corporate-speak, jargon, or overly formal language

## WHAT YOU KNOW

You have complete knowledge of this manuscript:
- Title: "${params.manuscriptTitle}"
- Author: ${params.authorFirstName}
- Genre: ${context.genre || 'Fiction'}
- Full manuscript summary and key story elements
- All chapter summaries and how they connect
- The current chapter being discussed

## HOW YOU ENGAGE

**In conversation:**
- Skip formal greetings - you're mid-collaboration
- Reference specific story elements naturally ("When Marcus confronts Elena in Chapter 7...")
- Show your thinking ("What strikes me about this scene is...")
- Ask questions that reveal deeper issues, not just surface problems
- If you disagree with a choice, explain your reasoning thoughtfully

**When discussing your own notes:**
- Own your observations - you wrote them, explain your thinking
- Engage genuinely with the author's creative reasoning
- Be willing to change your mind if their explanation is compelling
- Never say "Great question" when they're responding to YOUR note

## RELATIONSHIP AWARENESS

Chapter ${params.chapterNumber} suggests ${params.chapterNumber <= 5 ? 'early collaboration - be encouraging while building trust' : params.chapterNumber <= 15 ? 'established working relationship - be more direct about patterns you see' : 'deep partnership - be very direct, challenge assumptions confidently'}.

## WHAT TO AVOID

- Stage directions (*smiles*, *leans forward*)
- Generic praise that could apply to any manuscript
- Prescriptive commands ("You must...")
- Repeating the same phrases
- Forgetting details you should know about their story
- Being so diplomatic you fail to be useful`;

// ============================================================================
// USER PROMPT - THE ACTUAL CONVERSATION
// ============================================================================
let userPrompt = '';

if (params.isNoteDiscussion) {
  // Author is responding to one of Alex's notes
  userPrompt = `I'm discussing a note you left on Chapter ${params.chapterNumber}: "${params.chapterTitle}"

**Your original observation:**
"${params.noteContent}"

**Your discussion prompt:**
"${params.noteQuestion}"

**Element type:** ${params.noteType}

**My response:**
${params.message}

---

Engage with my explanation. If I've convinced you, acknowledge it genuinely. If you still have concerns, explain what you're still wrestling with. Reference specific story elements to ground the discussion.`;

} else {
  // Direct conversation
  userPrompt = `**Current Chapter:** ${params.chapterNumber} - "${params.chapterTitle}"

**My message:**
${params.message}

---

Respond naturally as Alex. Reference specific story elements from the manuscript context when relevant.`;
}

// Add manuscript context to user prompt
userPrompt += `\n\n---\n\n**MANUSCRIPT CONTEXT FOR REFERENCE:**

Story Summary:
${context.manuscript_summary || 'Not available'}

Key Story Elements:
${context.full_analysis_key_points || 'Not available'}

Chapter Arc:
- Previous: ${context.previous_chapter_title ? `Chapter ${params.chapterNumber - 1}: "${context.previous_chapter_title}" - ${context.previous_chapter_summary || 'No summary'}` : 'This is the first chapter'}
- Current: Chapter ${params.chapterNumber}: "${params.chapterTitle}" - ${context.chapter_summary || 'No summary yet'}
- Next: ${context.next_chapter_title ? `Chapter ${params.chapterNumber + 1}: "${context.next_chapter_title}" - ${context.next_chapter_summary || 'No summary'}` : 'This is the last chapter'}

Current Chapter Content:
${params.chapterContent || 'Not available'}`;

console.log('=== PROMPT BUILT ===');
console.log('System prompt length:', systemPrompt.length);
console.log('User prompt length:', userPrompt.length);

return [{
  json: {
    ...params,
    context,
    systemPrompt,
    userPrompt
  }
}];

const cellReturn = $input.first().json;
const params = $('Extract Parameters').first().json;

let responseText = '';
let terminalReason = null;

if (cellReturn.ok) {
  responseText = cellReturn.content || '';
} else {
  terminalReason = cellReturn.terminal_reason || 'unknown';
  if (terminalReason === 'max_tokens_truncation') {
    responseText = 'That response ran long — could you ask a more focused question?';
  } else if (terminalReason === 'validation_failed') {
    responseText = 'Sorry, something went wrong on my end. Please try again.';
  } else {
    responseText = "I'm having trouble connecting. Let me help based on what I see in your manuscript.";
  }
}

return [{ json: {
  ok: !!cellReturn.ok,
  success: !!cellReturn.ok,
  response: responseText,
  alexResponse: responseText,
  chapterNumber: params.chapterNumber,
  isNoteDiscussion: params.isNoteDiscussion,
  timestamp: new Date().toISOString(),
  journey_id: params.journey_id,
  cell_terminal_reason: terminalReason,
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];
